SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(640, 480, "#dcebf7");
  SZGame2D.enableClassicControls("auto");
  let noChao = false;
  let chegou = false;
  let quedas = 0;
  let fase = 1;
  let recado = "Fase 1: passe o buraco e chegue à bandeira.";
  const pinguim = SZGame2D.createSprite({ x: 40, y: 300, w: 44, h: 48, image: "pinguim" });
  const gelo1 = SZGame2D.createSprite({ x: 0, y: 416, w: 230, h: 64, image: "gelo" });
  const gelo2 = SZGame2D.createSprite({ x: 320, y: 416, w: 320, h: 64, image: "gelo" });
  const geloDaFase2 = SZGame2D.createSprite({ x: 20, y: 300, w: 180, h: 24, image: "gelo" });
  const mar = SZGame2D.createSprite({ x: 0, y: 462, w: 640, h: 18, image: "mar" });
  const bandeira = SZGame2D.createSprite({ x: 572, y: 336, w: 40, h: 80, image: "bandeira" });
  // Quando acontecer
  SZGame2D.onKey("Space", () => {

  }, "pico_quadro_1_events_0");
  SZGame2D.onKey("Enter", () => {

  }, "pico_quadro_1_events_1");
  SZGame2D.onKey("ArrowUp", () => {

  }, "pico_quadro_1_events_2");
  SZGame2D.onOverlap(() => pinguim, () => mar, () => {

  }, "pico_quadro_1_events_3");
  SZGame2D.onOverlap(() => pinguim, () => bandeira, () => {

  }, "pico_quadro_1_events_4");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    noChao = false;
    SZGame2D.applyGravity(pinguim);
    SZGame2D.arrowsX(pinguim, 2);
    SZGame2D.applyVelocity(pinguim);
    SZGame2D.clampToScreen(pinguim, ctx);
    if (SZGame2D.spriteX(pinguim) < 230) {
      if (-44 < SZGame2D.spriteX(pinguim)) {
        if (368 < SZGame2D.spriteY(pinguim)) {
          if (SZGame2D.spriteY(pinguim) < 386) {
            pinguim.vx = 0; pinguim.vy = 368 - SZGame2D.spriteY(pinguim);
            SZGame2D.applyVelocity(pinguim);
            pinguim.vx = 0; pinguim.vy = 0;
            noChao = true;
          }
        }
      }
    }
    if (SZGame2D.spriteX(pinguim) < 640) {
      if (276 < SZGame2D.spriteX(pinguim)) {
        if (368 < SZGame2D.spriteY(pinguim)) {
          if (SZGame2D.spriteY(pinguim) < 386) {
            pinguim.vx = 0; pinguim.vy = 368 - SZGame2D.spriteY(pinguim);
            SZGame2D.applyVelocity(pinguim);
            pinguim.vx = 0; pinguim.vy = 0;
            noChao = true;
          }
        }
      }
    }
    if (fase === 2) {
      if (SZGame2D.spriteX(pinguim) < 200) {
        if (-24 < SZGame2D.spriteX(pinguim)) {
          if (252 < SZGame2D.spriteY(pinguim)) {
            if (SZGame2D.spriteY(pinguim) < 270) {
              pinguim.vx = 0; pinguim.vy = 252 - SZGame2D.spriteY(pinguim);
              SZGame2D.applyVelocity(pinguim);
              pinguim.vx = 0; pinguim.vy = 0;
              noChao = true;
            }
          }
        }
      }
    }
    SZGame2D.clear();
    SZGame2D.drawBackdrop(ctx, "pico");
    SZGame2D.drawLabel(ctx, "Pulo com apoio", 18, 32, "#1d3b5c", 25, "left");
    SZGame2D.drawLabel(ctx, "Setas andam, Espaço ou A pula. Chegue à bandeira.", 18, 61, "#1d3b5c", 16, "left");
    SZGame2D.drawSprite(ctx, mar);
    SZGame2D.drawSprite(ctx, gelo1);
    SZGame2D.drawSprite(ctx, gelo2);
    if (fase === 2) {
      SZGame2D.drawSprite(ctx, geloDaFase2);
    }
    SZGame2D.drawSprite(ctx, bandeira);
    SZGame2D.drawSprite(ctx, pinguim);
    SZGame2D.drawLabel(ctx, recado, 18, 92, "#1d3b5c", 15, "left");
    SZGame2D.drawScore(ctx, "Fase: ", fase, 18, 122, "#1d3b5c", 18);
    SZGame2D.drawScore(ctx, "Quedas: ", quedas, 120, 122, "#1d3b5c", 18);
    if (SZGame2D.sceneIs("fim")) {
      SZGame2D.drawLabel(ctx, "Fim de jogo. Enter começa de novo.", 180, 200, "#1d3b5c", 20, "left");
    }
  }, "pico_quadro_1_loops_0");
}, "__sz-project");

